use diesel::prelude::*;
use embedag_diesel::cte::{CteHierarchyBuilder, HierarchicalNode, HierarchyItem};
use embedag_example_receipts::{
    FinanceInvoice, InvoiceItem, ReceiptCategoryRecord, categorize_ticket_invoice,
    run_receipt_categories_postgres_migration, run_receipt_categories_sqlite_migration,
};

#[test]
fn test_macro_generated_table_config_and_context_for_llm() {
    // Verify that the table configuration is fully generated by the macro
    let config = ReceiptCategoryRecord::table_config();
    assert_eq!(config.table_name, "receipt_categories");
    assert_eq!(config.id_column, "category_id");
    assert_eq!(config.parent_column, "parent_category_id");
    assert_eq!(config.name_column, "category_name");
    assert!(config.description.is_some());

    // Verify that table context is formatted for feeding the LLM
    let context = ReceiptCategoryRecord::table_context();
    assert!(context.contains("Table: receipt_categories"));
    assert!(context.contains("- Key Column: category_id"));
    assert!(context.contains("- Parent Column: parent_category_id"));
    assert!(context.contains("- Label Column: category_name"));
    assert!(context.contains("Retail purchase ticket receipt categories hierarchy"));
}

#[test]
fn test_macro_generated_crud_operations_on_receipt_categories() {
    let mut conn = diesel::SqliteConnection::establish(":memory:").expect("in-memory sqlite");
    run_receipt_categories_sqlite_migration(&mut conn).expect("custom receipt migration");

    // 1. Single Insert via macro-generated method
    let root = ReceiptCategoryRecord {
        category_id: "store_root".into(),
        parent_category_id: None,
        category_name: "SuperMarket".into(),
        entity_level: "store_root".into(),
    };
    let count = root.insert_sqlite(&mut conn).expect("insert single");
    assert_eq!(count, 1);

    // 2. Batch Insert via macro-generated method
    let batch = vec![
        ReceiptCategoryRecord {
            category_id: "dept_produce".into(),
            parent_category_id: Some("store_root".into()),
            category_name: "Produce".into(),
            entity_level: "department".into(),
        },
        ReceiptCategoryRecord {
            category_id: "cat_apples".into(),
            parent_category_id: Some("dept_produce".into()),
            category_name: "Apples".into(),
            entity_level: "category".into(),
        },
    ];
    let batch_count =
        ReceiptCategoryRecord::insert_batch_sqlite(&batch, &mut conn).expect("batch insert");
    assert_eq!(batch_count, 2);

    // 3. Update via macro-generated method
    let updated_root = ReceiptCategoryRecord {
        category_id: "store_root".into(),
        parent_category_id: None,
        category_name: "SuperMarket Flagship".into(),
        entity_level: "store_root".into(),
    };
    let updated = updated_root.update_sqlite(&mut conn).expect("update");
    assert_eq!(updated, 1);

    // 4. Delete via macro-generated method
    let deleted =
        ReceiptCategoryRecord::delete_by_id_sqlite(&mut conn, "cat_apples").expect("delete");
    assert_eq!(deleted, 1);
}

#[test]
fn test_developer_custom_migration_and_invoice_categorization_cte_sqlite() {
    let mut conn = diesel::SqliteConnection::establish(":memory:").expect("in-memory sqlite");

    // 1. Run developer's custom migration (does NOT use hardcoded semantic_nodes/edges)
    run_receipt_categories_sqlite_migration(&mut conn).expect("custom receipt migration");

    // 2. Input pure purchase invoice DTO (no semantic flags)
    let ticket = FinanceInvoice {
        invoice_id: "inv_101".into(),
        merchant_id: "FreshMarket".into(),
        date: embedag_example_receipts::finance::parse_date("2026-10-12"),
        purchase_content: None,
        items: vec![
            InvoiceItem::new("item_1", "Organic Oat Milk", 3.99, 2, None),
            InvoiceItem::new("item_2", "Artisan Sourdough Loaf", 4.50, 1, None),
            InvoiceItem::new("item_3", "Paper Towels", 2.25, 2, None),
        ],
        total: 16.98,
    };

    // 3. Derive hierarchical categories from invoice items
    let categories: Vec<ReceiptCategoryRecord> = categorize_ticket_invoice(&ticket);
    assert!(
        !categories.is_empty(),
        "Must generate category hierarchy from ticket"
    );

    // Verify auto-derived HierarchicalNode trait implementation
    for cat in &categories {
        assert_eq!(cat.node_id(), cat.category_id);
        assert_eq!(cat.node_name(), &cat.category_name);
    }

    // 4. Fill developer's custom table using macro-generated type-safe Diesel batch insert
    ReceiptCategoryRecord::insert_batch_sqlite(&categories, &mut conn)
        .expect("insert category rows via macro-generated type-safe Diesel batch");

    // 5. Query hierarchical lineage using macro-generated table_config and CteHierarchyBuilder
    let config = ReceiptCategoryRecord::table_config();

    let oat_milk_item = categories
        .iter()
        .find(|c| c.category_name == "Organic Oat Milk")
        .expect("oat milk item exists");

    let ancestors: Vec<HierarchyItem> = CteHierarchyBuilder::fetch_ancestors_sqlite(
        &mut conn,
        &config,
        &oat_milk_item.category_id,
        10,
    )
    .expect("ancestors recursive CTE query");

    // Ancestor lineage must be: Milk & Dairy (depth 1) -> Dairy & Plant Alternatives (depth 2) -> FreshMarket (depth 3)
    assert_eq!(
        ancestors.len(),
        3,
        "Must retrieve 3 levels of ancestor categories"
    );
    assert_eq!(ancestors[0].depth, 1);
    assert_eq!(ancestors[0].name, "Milk & Dairy");
    assert_eq!(ancestors[1].depth, 2);
    assert_eq!(ancestors[1].name, "Dairy & Plant Alternatives");
    assert_eq!(ancestors[2].depth, 3);
    assert_eq!(ancestors[2].name, "FreshMarket");

    // 6. Query all descendant subcategories from the store root node using macro-generated table_config
    let store_root = categories
        .iter()
        .find(|c| c.entity_level == "store_root")
        .expect("store root exists");

    let descendants: Vec<HierarchyItem> = CteHierarchyBuilder::fetch_descendants_sqlite(
        &mut conn,
        &config,
        &store_root.category_id,
        10,
    )
    .expect("descendants recursive CTE query");

    // Total descendants must include 3 departments, 3 subcategories, and 3 items = 9 nodes
    assert_eq!(
        descendants.len(),
        9,
        "Must traverse all 9 downstream descendant category nodes"
    );

    // Verify depth ordering
    let depths: Vec<i32> = descendants.iter().map(|d| d.depth).collect();
    assert!(
        depths.windows(2).all(|w| w[0] <= w[1]),
        "Descendants must be returned ordered by depth"
    );
}

#[test]
fn test_diamond_dag_deduplication_with_recursive_not_all() {
    let mut conn = diesel::SqliteConnection::establish(":memory:").expect("in-memory sqlite");
    run_receipt_categories_sqlite_migration(&mut conn).expect("custom receipt migration");

    let diamond_rows = vec![
        ReceiptCategoryRecord {
            category_id: "root".into(),
            parent_category_id: None,
            category_name: "General Retail".into(),
            entity_level: "root".into(),
        },
        ReceiptCategoryRecord {
            category_id: "cat_a".into(),
            parent_category_id: Some("root".into()),
            category_name: "Specialty Food".into(),
            entity_level: "dept".into(),
        },
        ReceiptCategoryRecord {
            category_id: "cat_b".into(),
            parent_category_id: Some("root".into()),
            category_name: "Organic Pantry".into(),
            entity_level: "dept".into(),
        },
        ReceiptCategoryRecord {
            category_id: "leaf".into(),
            parent_category_id: Some("cat_a".into()),
            category_name: "Artisan Honey".into(),
            entity_level: "item".into(),
        },
        ReceiptCategoryRecord {
            category_id: "leaf_alt".into(),
            parent_category_id: Some("cat_b".into()),
            category_name: "Artisan Honey".into(),
            entity_level: "item".into(),
        },
    ];

    ReceiptCategoryRecord::insert_batch_sqlite(&diamond_rows, &mut conn)
        .expect("insert diamond rows");

    // Traversal using macro-generated table_config directly from model
    let config = ReceiptCategoryRecord::table_config();
    let ancestors =
        CteHierarchyBuilder::fetch_ancestors_dedup_sqlite(&mut conn, &config, "leaf", 5)
            .expect("ancestors dedup");

    assert!(!ancestors.is_empty());
    assert_eq!(ancestors[0].name, "Specialty Food");
    assert_eq!(ancestors[1].name, "General Retail");
}

#[tokio::test]
#[ignore = "starts a Postgres container: runs in the persistence-testcontainers and coverage jobs"]
async fn test_developer_custom_migration_and_invoice_categorization_cte_postgres() {
    use diesel_async::{AsyncConnection, AsyncPgConnection};
    use embedag_diesel::harness::PostgresHarness;

    let harness = PostgresHarness::start()
        .await
        .expect("start postgres harness");
    let client = harness.connect().await.expect("connect client");

    // 1. Run developer's custom PostgreSQL migration
    run_receipt_categories_postgres_migration(&client)
        .await
        .expect("run pg custom receipt migration");

    // 2. Establish diesel-async AsyncPgConnection
    let db_url = format!(
        "postgres://postgres:postgres@{}:{}/postgres",
        harness.host, harness.port
    );
    let mut async_conn = AsyncPgConnection::establish(&db_url)
        .await
        .expect("connect async pg connection");

    // 3. Prepare pure ticket DTO and generate categories
    let ticket = FinanceInvoice {
        invoice_id: "inv_pg_101".into(),
        merchant_id: "WholeOrganics".into(),
        date: embedag_example_receipts::finance::parse_date("2026-10-12"),
        purchase_content: None,
        items: vec![
            InvoiceItem::new("item_1", "Fresh Whole Milk", 4.99, 1, None),
            InvoiceItem::new("item_2", "French Baguette Bread", 3.50, 2, None),
        ],
        total: 11.99,
    };

    let categories = categorize_ticket_invoice(&ticket);

    // 4. Fill custom table using macro-generated type-safe Diesel async batch insert
    ReceiptCategoryRecord::insert_batch_pg_async(&categories, &mut async_conn)
        .await
        .expect("insert category rows via macro-generated type-safe Diesel async batch");

    let config = ReceiptCategoryRecord::table_config();

    let milk_item = categories
        .iter()
        .find(|c| c.category_name == "Fresh Whole Milk")
        .expect("milk item");

    // 5. Query ancestors via macro-generated config on PostgreSQL
    let ancestors = CteHierarchyBuilder::fetch_ancestors_pg_async(
        &mut async_conn,
        &config,
        &milk_item.category_id,
        10,
    )
    .await
    .expect("fetch ancestors pg async");

    assert_eq!(ancestors.len(), 3);
    assert_eq!(ancestors[0].depth, 1);
    assert_eq!(ancestors[0].name, "Milk & Dairy");
    assert_eq!(ancestors[1].depth, 2);
    assert_eq!(ancestors[1].name, "Dairy & Plant Alternatives");
    assert_eq!(ancestors[2].depth, 3);
    assert_eq!(ancestors[2].name, "WholeOrganics");
}

#[test]
fn test_degree_bounded_descendant_cte_sqlite() {
    let mut conn = diesel::SqliteConnection::establish(":memory:").expect("in-memory sqlite");
    run_receipt_categories_sqlite_migration(&mut conn).expect("custom receipt migration");

    let mut rows = vec![ReceiptCategoryRecord {
        category_id: "root_dept".into(),
        parent_category_id: None,
        category_name: "SuperMarket".into(),
        entity_level: "root".into(),
    }];

    for i in 1..=10 {
        rows.push(ReceiptCategoryRecord {
            category_id: format!("sub_{i}"),
            parent_category_id: Some("root_dept".into()),
            category_name: format!("Category {i:02}"),
            entity_level: "sub".into(),
        });
    }

    ReceiptCategoryRecord::insert_batch_sqlite(&rows, &mut conn).expect("batch insert");

    // Unbounded traversal: returns all 10 children
    let config_unbounded = ReceiptCategoryRecord::table_config();
    let unb_desc =
        CteHierarchyBuilder::fetch_descendants_sqlite(&mut conn, &config_unbounded, "root_dept", 5)
            .expect("unbounded descendants");
    assert_eq!(unb_desc.len(), 10);

    // Degree-bounded traversal: limits to 3 children per level
    let config_bounded = ReceiptCategoryRecord::table_config().with_max_breadth_per_node(3);
    let bounded_desc =
        CteHierarchyBuilder::fetch_descendants_sqlite(&mut conn, &config_bounded, "root_dept", 5)
            .expect("bounded descendants");
    assert_eq!(bounded_desc.len(), 3);
}
